#!/usr/bin/env bash
# principle: feedback_a_parity_baseline_synced_by_copying_the_rendered_file_absorbs_its_header_and_indent
#
# `deploy/k3s/` 下面是 **parity 基线兼 GitOps 拉取端**，不是渲染产物：它的缩进、头部、
# 文件切分都是手写的，与 `deploy/rendered/k3s-single/` 逐字节不同本来就是正常的
# （投递方式不同、标签不同）。于是「有人把渲染产物整份 `cp` 过来」这件事在字段级
# parity 上是**绿的**——字段一样，多出来的只是头部三行与四格缩进。
#
# 2026-10-23 实测：一次这样的 `cp` 让一笔提交变成 6247 行，真正的内容改动只有一条告警规则
# 的 10 行；`git log -p` 与 blame 从此指向一次格式化提交。
#
# 能机检的只有一个人的信号：**整份镜像**的清单头上会带着渲染器的
# `# GENERATED by deploy/scripts/render-deploy.sh` 那一行。所以这条门守的不是「别抄」，
# 而是「抄了要说出来」：
#   1. 静态目录里带着那一行的文件，正好是下面表里声明过的那几个；多出来一个就红，
#      问的就是「你是要整份镜像（那就声明），还是只想改内容（那就别 `cp`）」；
#   2. 表里的每个文件都还在、都还带着那一行：改名或还原之后表不能停在旧名单上，
#      否则这份人口在悄悄缩小。
#
# 判不到的：有人先 `cp` 再把头部三行删掉、缩进改回去。那之后的文件与一份手写基线同形，
# 树上看不出来——这一条只能在 `git diff --stat` 那一面读（一条规则的改动应该是十来行，
# 出现几千行就是拷了文件）。
#
# 跑法：bash deploy/scripts/tests/static-baselines-declare-whole-file-mirrors.test.sh
#       bash deploy/scripts/tests/static-baselines-declare-whole-file-mirrors.test.sh <树根>  # 夹具用
set -uo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "${here}/../../.." && pwd)"
root="${1:-${repo}}"
static_dir="${root}/deploy/k3s"
claim="# GENERATED by deploy/scripts/render-deploy.sh"

pass=0; fail=0
ok()  { pass=$((pass + 1)); printf 'ok    - %s\n' "$1"; }
bad() { fail=$((fail + 1)); printf 'FAIL- %s\n' "$1"; }

# 声明过的整份镜像。一行的格式是 `<相对 deploy/k3s 的文件名><TAB><为什么它是整份镜像>`。
declared=(
    $'process-census-daemonset.yaml\t由渲染产物整份对齐（sync-static-manifests.sh 第 3 段），字段与头部都不是手写的'
)

if [ ! -d "$static_dir" ]; then
    printf 'FAIL- 找不到静态清单目录：%s\\n' "$static_dir" >&2
    exit 1
fi

# 人口：静态目录里带那一行头部的文件（只认顶格的第一行区块，不认正文里的引用）。
mapfile -t carriers < <(grep -rlF -- "$claim" --include='*.yaml' "$static_dir" 2>/dev/null \
    | sed "s|^${static_dir}/||" | sort)

if [ "${#carriers[@]}" -gt 0 ]; then
    ok "静态目录里数得出整份镜像的候选（${#carriers[@]} 份）"
else
    ok "静态目录里今天没有整份镜像的候选（这一格不是失败：没有比有更安全）"
fi

declare -A reason=()
for row in "${declared[@]}"; do
    reason["${row%%$'\t'*}"]="${row#*$'\t'}"
done

# 1. 多出来的：带头部却不在表里。
undeclared=()
for f in "${carriers[@]:-}"; do
    [ -n "$f" ] || continue
    [ -n "${reason[$f]:-}" ] || undeclared+=("$f")
done
if [ "${#undeclared[@]}" -eq 0 ]; then
    ok "没有未声明的整份镜像"
else
    bad "这些静态清单是渲染产物的整份镜像，却没有声明：${undeclared[*]}
        整份镜像会把渲染器的头部与缩进一起搬进基线（2026-10-23 那一笔就是这么变成
        6247 行的）。要整份镜像就在这张表里加一行并写清为什么；只想改内容就别 cp。"
fi

# 2. 表里的必须还在、还带着那一行。
for f in "${!reason[@]}"; do
    if [ ! -f "${static_dir}/${f}" ]; then
        bad "表里的整份镜像不在了：${f}（改名或删掉了？表停在旧名单上，这一格就守不住任何东西）"
        continue
    fi
    if ! grep -qF -- "$claim" "${static_dir}/${f}"; then
        bad "表里的整份镜像没有那一行头部了：${f}（还原成手写基线了就把它从表里删掉）"
        continue
    fi
    ok "声明过的整份镜像仍在：${f}"
done

# 给了树根就是在跑夹具：只判、不印摘要、不再套夹具（否则递归）。
if [ -n "${1:-}" ]; then
    [ "$fail" -eq 0 ]
    exit $?
fi

# ---- 夹具：证明上面这几格会红，而不是每次都绿 -------------------------------
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

fixture() { # <用例名> [额外文件…]；印出树根
    local d="$work/$1"; shift
    mkdir -p "$d/deploy/k3s"
    printf '%s\n' "$claim" > "$d/deploy/k3s/process-census-daemonset.yaml"
    printf 'apiVersion: v1\nkind: Service\n' >> "$d/deploy/k3s/process-census-daemonset.yaml"
    local f
    for f in "$@"; do
        { printf '%s\n' "$claim"; printf 'apiVersion: v1\nkind: Service\n'; } > "$d/deploy/k3s/$f"
    done
    printf '%s' "$d"
}

# 1. 多出来的整份镜像：红，并点名那一份。
d="$(fixture extra "copied-elsewhere.yaml")"
out="$(bash "$0" "$d" 2>&1)"; rc=$?
if [ "$rc" -ne 0 ]; then ok "多一份未声明的整份镜像 ⇒ 红"; else bad "1 期望红，实得绿：$out"; fi
case "$out" in *"copied-elsewhere.yaml"*) ok "点名了多出来的那一份" ;; *) bad "1 没点名：$out" ;; esac

# 2. 表里的文件不见了：红，并说清是名单停在旧处。
d="$work/gone"; mkdir -p "$d/deploy/k3s"
printf 'apiVersion: v1\nkind: Service\n' > "$d/deploy/k3s/something-else.yaml"
out="$(bash "$0" "$d" 2>&1)"; rc=$?
if [ "$rc" -ne 0 ]; then ok "声明的整份镜像不在了 ⇒ 红"; else bad "2 期望红，实得绿：$out"; fi
case "$out" in *"process-census-daemonset.yaml"*) ok "点名了不在的那一份" ;; *) bad "2 没点名：$out" ;; esac

# 3. 表里的文件还在但头部没了（还原成手写基线）：红。
d="$work/stripped"; mkdir -p "$d/deploy/k3s"
printf 'apiVersion: v1\nkind: Service\n' > "$d/deploy/k3s/process-census-daemonset.yaml"
out="$(bash "$0" "$d" 2>&1)"; rc=$?
if [ "$rc" -ne 0 ]; then ok "头部没了仍在表里 ⇒ 红"; else bad "3 期望红，实得绿：$out"; fi

# 4. 干净的小树：不白红。
d="$(fixture clean)"
out="$(bash "$0" "$d" 2>&1)"; rc=$?
if [ "$rc" -eq 0 ]; then ok "干净的小树 ⇒ 绿"; else bad "4 期望绿，实得红：$out"; fi

printf '\nstatic-baselines-declare-whole-file-mirrors.test.sh: %d passed, %d failed\n' "$pass" "$fail"
[ "$fail" -eq 0 ]
